		// arrow down to "Yes, I accept" before confirming.
		if strings.Contains(content, "Yes, I accept") {
			_ = s.SendKeys("Down")
			time.Sleep(200 * time.Millisecond)
		}
		_ = s.SendKeys("Enter")
		time.Sleep(500 * time.Millisecond)

